REPLACE INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('volkstribun', 'Volkstribun', '["Volkstribunen","Tribunen"]', 'Der Volkstribun (tribunus plebis) war eines der wichtigsten politischen Ämter der römischen Republik und diente als Schutzorgan der Plebejer gegen die Willkür der patrizischen Magistrate. Das Amt entstand im Jahr 494 v. Chr. nach dem ersten Ständekampf, als die Plebejer durch ihren Auszug auf den Heiligen Berg (secessio plebis) die Einrichtung eigener Amtsträger erzwangen.\n\nDie Volkstribunen besaßen außergewöhnliche Befugnisse: Sie waren sakrosankt (sacrosanctitas), das heißt ihre Person war unantastbar und heilig – wer einen Tribun angriff, konnte straflos getötet werden. Ihr wichtigstes Instrument war das Vetorecht (intercessio), mit dem sie gegen jeden Beschluss eines Magistrats, des Senats oder sogar gegen Gesetzesvorlagen Einspruch erheben konnten. Dieses absolute Veto machte sie zu mächtigen politischen Akteuren.\n\nUrsprünglich gab es zwei Volkstribunen, ihre Zahl wurde später auf zehn erhöht. Sie wurden ausschließlich von der Plebs in den Tributkomitien gewählt und konnten nur Plebejer sein. Die Tribunen durften Rom während ihrer Amtszeit nicht verlassen und mussten ihre Häuser Tag und Nacht für hilfesuchende Bürger offenhalten. Sie hatten das Recht, Versammlungen der Plebs (concilium plebis) einzuberufen und Senatssitzungen beizuwohnen.\n\nBerühmte Volkstribunen wie die Gracchen (Tiberius und Gaius Gracchus) nutzten das Amt für weitreichende Sozialreformen, was zu heftigen politischen Konflikten führte. In der späten Republik wurde das Tribunat oft als Sprungbrett für ehrgeizige Politiker genutzt. Gaius Iulius Caesar begann seine politische Karriere ebenfalls in diesem Amt. Nach der Errichtung des Prinzipats behielt Augustus die tribunizische Gewalt (tribunicia potestas) für sich bei, wodurch das Amt faktisch seiner ursprünglichen Macht beraubt wurde.', 'Politik', '', '["plebejer","republik","senat","Patricier","Konsul"]', '{"en":{"term":"Tribune of the Plebs","definition":"An office in the Roman Republic created to represent the interests of the plebeians (the common people) against those of the patricians (the nobility). Tribunes of the Plebs possessed extensive powers, especially the right of veto (intercessio) against measures of all other magistrates.","etymology":"","category":"Politics","variants":[]},"la":{"term":"Tribunus Plebis","definition":"Magistratus in Re Publica Romana creatus ad tuendas plebis utilitates contra patricios. Tribuni plebis potestates magnas habebant, praecipue ius intercessionis adversus actus omnium aliorum magistratuum.","etymology":"","category":"Res Publica","variants":[]}}');
REPLACE INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('legion', 'Legion', '[]', 'Die Legion war die Grundeinheit des römischen Heeres und bildete das Rückgrat der militärischen Macht Roms. Eine Legion bestand in der Kaiserzeit aus etwa 4.800 bis 6.000 schwer bewaffneten Infanteristen (Legionären), die alle römische Bürger sein mussten. Die organisatorische Struktur einer Legion war hochgradig entwickelt: Sie war in 10 Kohorten unterteilt, wobei jede Kohorte wiederum aus mehreren Zenturien (etwa 80 Mann) bestand, die von einem Centurio befehligt wurden. Die erste Kohorte hatte eine Sonderstellung mit doppelter Stärke und beherbergte den Legionsadler (aquila), das wichtigste Symbol der Legion. Zu einer Legion gehörten zudem etwa 120 Reiter für Aufklärungs- und Meldedienste sowie zahlreiche Hilfstruppen (Auxiliartruppen) aus nicht-römischen Völkern. Die Legion war eine hochmobile, disziplinierte Kampfeinheit, die nicht nur im Kampf, sondern auch beim Bau von Straßen, Brücken und Befestigungen eingesetzt wurde. Jede Legion trug eine Nummer und oft einen Beinamen, der an Siege oder den Gründer erinnerte.CenturioGladiusLimes', 'Militär', 'Von lateinisch ''legio'' - Auswahl, Aushebung. Abgeleitet von ''legere'' (auswählen, sammeln). Ursprünglich bezeichnete es die gesamte Streitmacht, die zum Kriegsdienst ausgehoben wurde.', '[]', '{"en":{"term":"Legion","definition":"A Legion was the largest military unit of the Roman army, consisting of about 4,000 to 6,000 heavy infantry (legionaries), along with cavalry and auxiliary troops. It was the backbone of Roman military power and conquest.","etymology":"From Latin ''legere'' (to choose, levy).","category":"Military","variants":["Legio"]},"la":{"term":"Legio","definition":"Legio erat unitas militaris maxima exercitus Romani, quae e quattuor ad sex milibus peditum (legionariorum) et equitibus constabat. Robur imperii Romani erat.","etymology":"A verbo ''legere'', quia milites legebantur.","category":"Res Militaris","variants":[]}}');
REPLACE INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('senator', 'Senator', '[]', 'Mitglied des römischen Senats, des höchsten Regierungsorgans der römischen Republik. Senatoren waren meist ehemalige Magistrate und bildeten eine Elite aus etwa 300-600 Männern.', 'Politik', 'Von lateinisch ''senex'' (der Alte, Greis). Der Begriff betont die Weisheit und Erfahrung, die von den Senatsmitgliedern erwartet wurde.', '[]', '{"en":{"term":"Senator","definition":"A Senator was a member of the Roman Senate, the primary consultative and governing body of the Roman Republic and later the Empire. Historically derived from the council of elders (*senex*), the Senate reached about 300 to 600 members, mostly consisting of former high-ranking magistrates (cursus honorum). Senators held their seats for life, though they could be removed by censors for misconduct. They exercised immense authority over foreign policy, state finances, and the assignment of provincial commands. While the Senate''s advice (*senatus consultum*) was technically non-binding, it held massive political weight until the rise of imperial autocracy eclipsed its traditional power.","etymology":"From Latin ''senex'' (old man), implying a council of elders.","category":"Politics","variants":["Patres Conscripti"]},"la":{"term":"Senator","definition":"Senator erat socius Senatus Romani, qui fuit maximum consilium rei publicae. Huic ordini senatorio adhaerebant plerumque viri qui magistratus (sicut quaesturam aut praeturam) sustinuerant. Senatores de legibus, aerario et bellis consulebant; eorum ''senatus consulta'' magnam auctoritatem apud magistratus et populum habuerunt. In senatu auctoritas et sapientia (itaque nomen a ''senex'') praecipuae habebantur. Augustus et successores eius potestatem senatus paulatim minuerunt, sed dignitas senatoria per saecula mansit.","etymology":"A verbo ''senex''.","category":"Res Publica","variants":["Patres"]}}');
REPLACE INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('praetor', 'Praetor', '["Praetoren","Praetur","Proprätor"]', 'Der Praetor war ein hoher Magistrat der römischen Republik und stand in der Ranghierarchie direkt unter den Konsuln. Die Praetur war ein zentrales Amt im cursus honorum, dem traditionellen Karriereweg römischer Politiker. Praetoren waren primär für die Rechtsprechung zuständig und leiteten Gerichtsverfahren in Rom. Der praetor urbanus richtete über Rechtsstreitigkeiten zwischen römischen Bürgern, während der praetor peregrinus für Fälle mit Beteiligung von Ausländern zuständig war. Mit der Expansion Roms wuchs die Anzahl der Praetoren von ursprünglich einem auf bis zu acht oder mehr, da sie auch als Statthalter in den Provinzen eingesetzt wurden. Praetoren verfügten über imperium, die höchste Amtsgewalt, wenn auch in geringerem Maße als Konsuln. Sie konnten militärische Kommandos übernehmen und Armeen führen. Nach ihrer Amtszeit wurden viele Praetoren als Proprätoren in die Provinzen entsandt, wo sie als Statthalter fungierten. Das Amt war ein Sprungbrett zum Konsulat, dem höchsten Amt der Republik.', 'Politik', 'Von lateinisch ''praeire'' (vorangehen, vorführen). Ursprünglich bezeichnete es den militärischen Anführer, später auch den Gerichtsvorsteher.', '["Konsul","Senator","Imperium"]', '{"en":{"term":"Praetor","definition":"The Praetor was a magistrate of the Roman Republic, ranking below the consul. They were primarily responsible for the administration of justice and could also command armies. The ''Praetor Urbanus'' handled cases between citizens.","etymology":"From Latin ''praeire'' (to go before, lead).","category":"Politics","variants":["Praetor Urbanus","Praetor Peregrinus"]},"la":{"term":"Praetor","definition":"Praetor erat magistratus populi Romani cum imperio, qui ius dicebat et exercitus ducere poterat. Secundus a consule dignitate fuit. Praetor Urbanus ius inter cives dixit.","etymology":"A verbo ''praeire''.","category":"Res Publica","variants":[]}}');
REPLACE INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('centurio', 'Centurio', '[]', 'Ein Centurio (Zenturio) war ein Berufsoffizier der römischen Armee, der eine Centuria (etwa 80 Mann) kommandierte. Centurionen waren das Rückgrat der militärischen Führung, verantwortlich für Disziplin, Training und die Kampffähigkeit ihrer Einheit. Sie trugen charakteristische Helme mit Querbüschen und einen Weinstock (vitis) als Rangabzeichen.', 'Militär', 'Von lateinisch ''centum'' (hundert), da ursprünglich ein Centurio hundert Soldaten befehligte. Die Größe wurde später auf etwa 80 Mann reduziert, der Name blieb jedoch erhalten.', '["Legio"]', '{"en":{"term":"Centurion","definition":"","etymology":"","category":"Military","variants":[]},"la":{"term":"Centurio","definition":"","etymology":"","category":"Militaris","variants":[]}}');
REPLACE INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('patricier', 'Patricier', '["Patrizier"]', 'Die Patricier waren die Angehörigen der alteingesessenen aristokratischen Oberschicht des antiken Rom und bildeten in der Frühzeit der römischen Republik die exklusive herrschende Elite. Der Begriff leitet sich von ''patres'' (Väter) ab und bezog sich ursprünglich auf die Nachkommen der ersten Senatoren, die Romulus angeblich ernannt hatte. Patricier genossen jahrhundertelang ein Monopol auf politische und religiöse Ämter - nur sie konnten Konsuln, Praetoren oder Pontifices werden. Sie verfügten über das ausschließliche Recht, die Auspizien zu nehmen, also den Willen der Götter zu deuten.\n\nDie patricische Vorherrschaft führte zum jahrhundertelangen Ständekonflikt mit den Plebejern, der einfachen Bürgerschaft. Durch die Leges Liciniae Sextiae (367 v. Chr.) wurde festgelegt, dass einer der beiden Konsuln ein Plebejer sein musste. Die Lex Hortensia (287 v. Chr.) erklärte plebiszitäre Beschlüsse für das gesamte Volk bindend. Trotz dieser politischen Öffnung blieben patricische Familien lange einflussreich. Zu den berühmtesten patricischen Geschlechtern zählten die Fabier, Claudier, Cornelier und Julier (aus denen Julius Caesar stammte).\n\nPatricier zeichneten sich durch besondere Privilegien aus: Sie trugen rote Schuhe (calcei patrici), ihre Namen wurden in speziellen Listen geführt, und sie bildeten geschlossene Heiratskreise. Ihr Reichtum basierte auf Landbesitz und Klientelverhältnissen. In der späten Republik verlor die Unterscheidung zwischen Patriciern und Plebejern an Bedeutung, da sich eine neue Nobilität aus beiden Ständen bildete. Kaiser Konstantin belebte den Patriciertitel später als Ehrentitel neu.', 'Gesellschaft', 'Von lateinisch ''pater'' (Vater). Die Patricier waren Nachkommen der ersten Senatoren, die von den ''patres'' (Vätern) abstammten.', '["Plebejer","Senator"]', '{"en":{"term":"Patrician","definition":"The Patricians were the members of the long-established aristocratic upper class of ancient Rome and formed the exclusive ruling elite in the early days of the Roman Republic. The term derives from ''patres'' (fathers). They enjoyed a monopoly on political and religious offices for centuries.","etymology":"From Latin ''pater'' (father).","category":"Society","variants":["Patricians"]},"la":{"term":"Patricius","definition":"Patricii fuerunt cives Romani ordinis senatorii, qui a ''patribus'' originem duxerunt. In libera re publica soli magistratus maiores et sacerdotia inire potuerunt. Nobilitas eorum antiquissima et auctoritas gravissima fuit.","etymology":"A verbo ''pater''.","category":"Societas","variants":["Patricii"]}}');
REPLACE INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('plebejer', 'Plebejer', '["Plebs"]', 'Die Plebejer waren die breite Bürgerschicht des antiken Rom, die nicht zur alteingesessenen aristokratischen Elite der Patricier gehörte. Der Begriff leitet sich von ''plebs'' (das Volk, die Menge) ab und umfasste ursprünglich alle freien römischen Bürger ohne patricischen Stammbaum - von wohlhabenden Kaufleuten und Handwerkern bis zu armen Bauern und Tagelohnern. In der Frühzeit der römischen Republik waren Plebejer von den höchsten politischen und religiösen Ämtern ausgeschlossen und litten unter wirtschaftlicher Ausbeutung und rechtlicher Benachteiligung.\n\nDer jahrhundertelange Ständekonflikt zwischen Plebejern und Patriciern prägte die römische Geschichte. Die Plebejer kämpften systematisch für Gleichberechtigung: Durch die Secessio plebis (Auszug der Plebejer) 494 v. Chr. erzwangen sie die Einrichtung der Volkstribunen, die ihre Interessen vertraten und ein Vetorecht gegen Senatsbeschlüsse hatten. Die Zwölftafelgesetze (450 v. Chr.) kodifizierten erstmals das römische Recht schriftlich. Die Lex Canuleia (445 v. Chr.) erlaubte Ehen zwischen Patriciern und Plebejern. Die Leges Liciniae Sextiae (367 v. Chr.) öffneten das Konsulat für Plebejer.\n\nMit der Zeit gelang wohlhabenden plebejischen Familien der Aufstieg in die politische Elite. Zusammen mit patricischen Familien bildeten sie die neue Nobilität - eine Amtsaristokratie, deren Status auf erfolgreichen politischen Karrieren beruhte. Berühmte plebejische Geschlechter waren die Caecilier, Livianer und Sempronnier. Die Volksversammlung der Plebejer (concilium plebis) wurde zu einem wichtigen Gesetzgebungsorgan. Trotz formaler Gleichstellung blieben wirtschaftliche Unterschiede: Die ''plebs urbana'' (städtische Massen) lebten oft in Armut.', 'Gesellschaft', 'Von lateinisch ''plebs'' (das Volk, die Menge). Bezeichnet die einfache Bevölkerung im Gegensatz zur patrizischen Oberschicht.', '["Patricier","Volkstribun"]', '{"en":{"term":"Plebeian","definition":"The Plebeians (plebs) were the broad class of free Roman citizens who were not members of the aristocratic-patrician elite. Their long struggle for political and social equality with the patricians, known as the ''Conflict of the Orders'', was a defining feature of the early Roman Republic. Through strategic withdrawals from the city (secessio plebis) starting in 494 BC, they secured the creation of the Plebeian Tribunes (tribuni plebis) and eventually gained legal recognition through the Twelve Tables (450 BC). Key milestones included the Lex Canuleia (445 BC), allowing intermarriage, and the Leges Liciniae Sextiae (367 BC), which opened the consulship to them. Over time, wealthy plebeian families merged with the patricians to form the new ruling elite (nobilitas).","etymology":"From Latin ''plebs'' (multitude, common people).","category":"Society","variants":["Plebs","Plebeians"]},"la":{"term":"Plebeius","definition":"Plebeii erant maior pars civium Romanorum, qui non ex patriciorum numeris nati sunt. Per multa saecula in ''certamine ordinum'' pro aequalitate iuris contra patricios pugnaverunt. Per secessiones (primam anno CDXCIV a.C.n.) tribunos plebis creavere, qui eorum libertatem defenderent. Codificatio iuris XII Tabulis (CDL a.C.n.) et apertio consulatus (CCCLXVII a.C.n.) gradus maximi ad aequalitatem fuerunt. Postremo plebeii divites cum patriciis novam nobilitatem formaverunt.","etymology":"A verbo ''plebs'' aut ''plere''.","category":"Societas","variants":["Plebs","Plebei"]}}');
REPLACE INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('forum-romanum', 'Forum Romanum', '["Forum"]', 'Das Forum Romanum war das politische, religiöse, wirtschaftliche und gesellschaftliche Zentrum des antiken Rom und gilt als das bedeutendste Forum des römischen Weltreichs. Dieser rechteckige Platz im Tal zwischen den Hügeln Kapitol und Palatin entwickelte sich ab dem 7. Jahrhundert v. Chr. vom ursprünglichen Marktplatz zum repräsentativen Machtzentrum des Imperiums. Hier befanden sich die wichtigsten öffentlichen Gebäude: die Curia (Senatsgebäude), die Basiliken für Gerichtsverhandlungen und Geschäfte, zahlreiche Tempel wie der Saturntempel und der Tempel der Vesta, sowie Triumphbögen und Ehrendenkmäler.\n\nDas Forum war der Schauplatz der bedeutendsten Ereignisse römischer Geschichte: Hier hielten Politiker ihre Reden von der Rednertribüne (Rostra), hier fanden Triumpfzüge siegreicher Feldherren statt, und hier versammelten sich die Bürger zu Volksversammlungen. Unter Julius Caesar und später Augustus wurde das Forum grundlegend umgestaltet und mit prächtigen Marmorgebäuden ausgestattet. Die Via Sacra, die heilige Straße, durchzog das Forum und verband es mit anderen wichtigen Bereichen der Stadt.\n\nIm täglichen Leben war das Forum der pulsierende Mittelpunkt der Stadt: Kaufleute boten ihre Waren an, Anwälte vertraten ihre Klienten, Philosophen debattierten, und Nachrichtenverkünder verbreiteten die neuesten Ereignisse. Die umgebenden Kolonnaden boten Schutz vor Sonne und Regen. Mit dem Niedergang Roms verfiel auch das Forum, wurde aber später zu einer der wichtigsten archäologischen Stätten der Welt.', 'Gesellschaft', 'Von lateinisch ''forum'' (Marktplatz, öffentlicher Platz). Das Forum war traditionell der zentrale Treffpunkt jeder römischen Stadt.', '["Curia","Senator","Basilika"]', '{"en":{"term":"Forum Romanum","definition":"The Forum Romanum was the political, religious, commercial, and social heart of ancient Rome. Situated in the valley between the Palatine and Capitoline Hills, it evolved from a simple marketplace into the representative center of the Roman Empire by the 7th century BC. It was home to key structures like the Curia (Senate House), major law courts known as basilicas, and temples such as those of Saturn and Vesta. It was the stage for public speeches (from the Rostra), triumphal processions, and political assemblies. Under Caesar and Augustus, it was extensively rebuilt in marble, becoming a grand symbol of imperial power.","etymology":"Latin ''forum'' (public square, market).","category":"Society","variants":["The Forum"]},"la":{"term":"Forum Romanum","definition":"Forum Romanum fuit centrum vitae politicae, religiosae et socialis Romae antiquae. Inter montes Palatium et Capitolium situm, a saeculo VII a.C.n. ab emporio simplici ad centrum imperii splendens crevit. Hic aedificia maxima erant, sicut Curia, basilicae iuridicae, et templa Saturni Vestaeque. In Foro oratores pro Rostris dixerunt, triumphi acti sunt, et populus convenit. Iulius Caesar et Augustus Forum marmore et monumentis exornaverunt.","etymology":"Verbum ''forum'' a ''foris'' (extra) derivatur.","category":"Societas","variants":["Forum"]}}');
REPLACE INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('aqudukt', 'Aquädukt', '[]', 'Ein Aquädukt ist ein künstlich angelegtes Wasserleitungsbauwerk, das Wasser über weite Strecken – oft viele Kilometer bis zu über 100 Kilometer – in eine Stadt oder Siedlung transportiert. Der Begriff bezeichnet sowohl die oberirdischen Bogenkonstruktionen, die uns heute als eindrückliche Ruinen begegnen, als auch die unterirdischen Leitungssysteme, die den größten Teil der antiken Wasserleitungen ausmachten.\n\nBesonders berühmt sind die römischen Aquädukte, die mit außerordentlicher ingenieurtechnischer Präzision gebaut wurden. Die Römer nutzten das Gefälleprinzip: Das Wasser floss ausschließlich durch die Schwerkraft, wobei die Leitungen ein konstantes, aber sehr geringes Gefälle aufwiesen – oft nur wenige Zentimeter pro Kilometer. Diese Präzision erforderte hochentwickelte Vermessungstechniken.\n\nDie spektakulären Bogenreihen, die wir heute bewundern, waren notwendig, um Täler zu überqueren, ohne dass die Wasserleitung zu tief verlaufen musste. Berühmte Beispiele sind der Pont du Gard in Südfrankreich (fast 50 Meter hoch), die Segovia-Aquädukt in Spanien oder die zahlreichen Aquädukte, die Rom mit Wasser versorgten, wie die Aqua Claudia.\n\nRom selbst wurde von elf großen Aquädukten versorgt, die täglich etwa eine Million Kubikmeter Wasser in die Stadt brachten – genug, um die Bedürfnisse von über einer Million Einwohnern zu decken. Das Wasser versorgte nicht nur private Haushalte, sondern vor allem die zahlreichen öffentlichen Brunnen, Thermen und die aufwendigen Latrinensysteme.\n\nDie Aquädukte wurden aus Stein, Ziegeln und dem berühmten römischen Beton (opus caementicium) gebaut. Ihre Robustheit zeigt sich daran, dass viele von ihnen – oder zumindest ihre Reste – bis heute überdauert haben. Einige wurden im Mittelalter und sogar in der Neuzeit weitergenutzt oder instandgesetzt.\n\nDie Konstruktion eines Aquädukts war eine gewaltige logistische und finanzielle Unternehmung. Sie erforderte nicht nur technisches Know-how, sondern auch die Mobilisierung enormer Ressourcen an Arbeitskräften, Baumaterialien und Kapital. Aquädukte galten daher als prestigeträchtige Bauprojekte, die den Ruhm und die Macht ihrer Auftraggeber demonstrierten.', 'Gesellschaft', 'Lateinisch: *aqua* = Wasser, *ductus* = Leitung/Führung (von *ducere* = führen). Das lateinische "aqua" gehört zu den grundlegenden indogermanischen Wörtern und ist verwandt mit gotisch "ahva" (Fluss) und althochdeutsch "aha" (Wasser, Fluss). Der Begriff bedeutet wörtlich "Wasserführung" oder "Wasserleitung".', '[]', '{"en":{"term":"Aqueduct","definition":"An Aqueduct (from ''aqua'' and ''ductus'') was a conduit built to transport fresh water over long distances into cities and industrial sites. Utilizing gravity and a precise, constant gradient (often dropping only a few inches per mile), Roman engineers created complex systems that included both underground channels and the iconic arched stone bridges used to span valleys. Rome was supplied by eleven major aqueducts, delivering about a million cubic meters of water daily to public baths, fountains, and private homes. Key examples include the Pont du Gard in France and the Aqua Claudia in Rome, many of which still stand today as testaments to Roman engineering.","etymology":"Latin ''aqua'' (water) + ''ducere'' (to lead).","category":"Architecture","variants":["Aquaeductus"]},"la":{"term":"Aquaeductus","definition":"Aquaeductus est canalis structilis ad aquam per longa spatia in urbes ducendam. Romani machinatores scientia summa canales fecerunt, qui aqua tantum gravitate ducebant, sicut Aqua Claudia Romae aut Pont du Gard in Gallia. Roma ipsa undecim aquaeductibus servata est, qui aquam ad thermas, fontes et domos privatas ferebant. Hic mos vivendi et luxus urbis sine aquaeductibus fieri non potuit.","etymology":"Ab ''aqua'' et ''ducere''.","category":"Architectura","variants":[]}}');
REPLACE INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('gladius', 'Gladius', '["Gladii"]', 'Der Gladius war das charakteristische Kurzschwert der römischen Legionäre und eine der effektivsten Nahkampfwaffen der Antike. Mit einer Klingenlänge von etwa 60-85 cm und einer Breite von 5-7 cm war der Gladius speziell für den Stoß optimiert, konnte aber auch zum Hieb verwendet werden. Die zweischneidige Klinge verfügte über eine scharfe Spitze und war aus hochwertigem Stahl geschmiedet. Römische Soldaten trugen das Schwert üblicherweise auf der rechten Seite, damit es beim Marschieren in enger Formation nicht mit dem großen Schild (Scutum) des Nebenmanns kollidierte.\n\nDer Name ''Gladius'' stammt möglicherweise vom lateinischen ''gladius'' (Schwert) ab, das wiederum keltischen Ursprungs sein könnte. Im Nahkampf war die römische Kampftaktik verheerend effektiv: Soldaten schlugen erst mit dem Schildbuckel zu, um den Gegner aus dem Gleichgewicht zu bringen, und führten dann einen schnellen Stoß mit dem Gladius in den ungeschützten Körper aus. Diese Technik war tödlicher als Hiebwaffen, da Stichverletzungen tiefer eindringen konnten. Die enge Formation der Legionäre (Testudo) ermöglichte diese Kampfweise ideal.\n\nEs gab verschiedene Gladius-Typen, die sich im Laufe der Jahrhunderte entwickelten: Der Gladius Hispaniensis (spanisches Schwert) aus der Republik-Zeit hatte eine längere, spitz zulaufende Klinge. Der Mainz-Typ aus der frühen Kaiserzeit hatte eine lange, schlanke Form. Der Pompeii-Typ wurde im 1. Jahrhundert n. Chr. populär und war kürzer und leichter. Der Gladius wurde so zum Symbol römischer Militärmacht - sogar das lateinische Wort für Schwert wurde zum Namensgeber für Gladiatoren.', 'Militär', 'Von lateinisch ''gladius'' (Schwert). Das Wort ist möglicherweise keltischen Ursprungs und wurde von den Römern übernommen.', '["Legion","Scutum","Centurio"]', '{"en":{"term":"Gladius","definition":"The Gladius was the primary sword of ancient Roman foot soldiers. It was a short, double-edged sword designed for stabbing and thrusting in close formation combat. It was the standard weapon of the legionaries for centuries.","etymology":"Latin ''gladius'' (sword). Akin to English ''claymore'' (via Celtic roots).","category":"Military","variants":["Gladius Hispaniensis"]},"la":{"term":"Gladius","definition":"Gladius erat ensis brevis militum Romanorum. Utraque parte acutus, ad pungendum aptus erat in pugna cominus. Telum praecipuum legionariorum per multa saecula fuit.","etymology":"Verbum Latinum, fortasse origine Celtica.","category":"Res Militaris","variants":[]}}');
